        const bars = hs.map((h, i) => h.rain > 0 ? `<rect x="${(x(i) - 100 / n * 0.3).toFixed(2)}" y="${(100 - h.rain * 0.26).toFixed(2)}" width="${(100 / n * 0.6).toFixed(2)}" height="${(h.rain * 0.26).toFixed(2)}" class="dlw-pbar"/>` : "").join("");
